var ErrPortRange = errors.New("port out of range")

func ParsePort(s string) (int, error) {
    port, err := strconv.Atoi(s)
    if err != nil {
        return 0, fmt.Errorf("parse port %q: %w", s, err)
    }
    if port < 1 || port > 65535 {
        return 0, fmt.Errorf("%q: %w", s, ErrPortRange)
    }
    return port, nil
}

port, err := ParsePort(raw)   // errors.Is(err, ErrPortRange) distinguishes the reason
if err != nil {
    return err                // the tuple itself is the short-circuit
}
use(port)
